static (bool Found,int Min,int Max) Bounds(int[] values)
{
    if(values.Length==0) return (false,0,0);
    int min=values[0],max=min; foreach(int n in values) {min=Math.Min(min,n);max=Math.Max(max,n);}
    return (true,min,max);
}

